{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Halcyon Threshold — Commitment Verifiability Tracker record",
  "version": "0.1.0",
  "type": "object",
  "required": [
    "id", "developer", "source_title", "source_url", "archive_url",
    "retrieved", "commitment_text", "category", "specificity",
    "trigger_clarity", "observability", "attestation", "consequence",
    "coder", "rubric_version", "status"
  ],
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^HT-CT-[0-9]{5}$",
      "description": "Stable identifier. Never reused, never renumbered."
    },
    "developer": { "type": "string", "description": "Organisation making the commitment." },
    "source_title": { "type": "string" },
    "source_url": { "type": "string", "format": "uri" },
    "archive_url": {
      "type": "string",
      "format": "uri",
      "description": "Web-archive snapshot. Required: source documents are revised without notice."
    },
    "retrieved": { "type": "string", "format": "date" },
    "published": {
      "type": ["string", "null"],
      "format": "date",
      "description": "Date the commitment was first published, if determinable."
    },
    "commitment_text": {
      "type": "string",
      "description": "Verbatim quotation. No paraphrase, no ellipsis that changes meaning."
    },
    "category": {
      "type": "string",
      "enum": [
        "pre-deployment-evaluation",
        "capability-threshold",
        "incident-disclosure",
        "model-transparency",
        "external-access",
        "security",
        "deployment-restriction",
        "governance-structure",
        "pause-or-halt",
        "other"
      ]
    },
    "specificity":     { "type": "integer", "minimum": 0, "maximum": 3 },
    "trigger_clarity": { "type": "integer", "minimum": 0, "maximum": 3 },
    "observability":   { "type": "integer", "minimum": 0, "maximum": 3 },
    "attestation":     { "type": "integer", "minimum": 0, "maximum": 3 },
    "consequence":     { "type": "integer", "minimum": 0, "maximum": 3 },
    "coder": { "type": "string", "description": "A, B, or ADJ for an adjudicated record." },
    "rubric_version": { "type": "string" },
    "status": {
      "type": "string",
      "enum": ["active", "withdrawn", "superseded", "disputed"],
      "description": "'withdrawn' means the clause disappeared from the source between quarters."
    },
    "developer_response": {
      "type": ["string", "null"],
      "description": "Verbatim reply received under right-of-reply. Published unedited."
    },
    "notes": { "type": "string" }
  },
  "additionalProperties": false
}
